package service

import (
	"context"
	"fmt"
	"time"

	"evalfixture/domain"
	"evalfixture/hash"
	"evalfixture/repository"
)

// Session grants access until ExpiresAt.
type Session struct {
	Email     string
	ExpiresAt time.Time
}

type AccessService struct {
	users      repository.UserRepository
	hasher     hash.Hasher
	sessionTTL time.Duration
}

func NewAccessService(users repository.UserRepository, hasher hash.Hasher, sessionTTL time.Duration) *AccessService {
	return &AccessService{users: users, hasher: hasher, sessionTTL: sessionTTL}
}

func (s *AccessService) Register(ctx context.Context, email, orgID, password string) error {
	user := domain.NewUser(email, orgID, password)
	if _, err := s.users.Save(ctx, user); err != nil {
		return fmt.Errorf("registering user: %w", err)
	}
	return nil
}

func (s *AccessService) GrantSession(ctx context.Context, email string) (Session, error) {
	user, err := s.users.GetByEmail(ctx, email)
	if err != nil {
		return Session{}, fmt.Errorf("granting session: %w", err)
	}
	return Session{
		Email:     user.Email(),
		ExpiresAt: time.Now().Add(s.sessionTTL),
	}, nil
}

func (s *AccessService) IsSessionValid(session Session) bool {
	return !session.ExpiresAt.Before(time.Now())
}

